use liq_ta::kernels::simd::*;
fn bits(x:f32)->u32 {if x.is_nan(){f32::NAN.to_bits()}else{x.to_bits()}}
fn main(){for len in 0..=65 {for mode in 0..6 {let mut x:Vec<f32>=(0..len).map(|i| {let a=f32::from(u8::try_from(i%11).unwrap())/7.0;if i%2==0{a}else{-a}}).collect();if mode==1 && len>0{x[len/2]=f32::NAN;}if mode==2 && len>0{x[len/2]=f32::INFINITY;}if mode==3{for(i,v)in x.iter_mut().enumerate(){*v=[1e8,1.0,-1e8,1.0][i%4];}}if mode==4{for(i,v)in x.iter_mut().enumerate(){*v=if i%2==0{0.0}else{-0.0};}}if mode==5{for(i,v)in x.iter_mut().enumerate(){*v=if i%2==0{f32::MIN_POSITIVE}else{-f32::MIN_POSITIVE};}}let y:Vec<f32>=x.iter().map(|v|v*0.75).collect();let mut output=vec![0.0;len];lagged_sub_f32(&x,&y,&mut output);println!("{len}:{mode} {:?} {:?}",[sum_f32(&x),min_f32(&x),max_f32(&x)].map(bits),output.into_iter().map(bits).collect::<Vec<_>>());}}}
